-- RUIM: N+1 em aplicação
const users = await db.query('SELECT * FROM users LIMIT 10'); // 1 query
for (const user of users) {
  const progress = await db.query(
    'SELECT COUNT(*) as lessons_completed FROM user_lesson_progress WHERE user_id = $1',
    [user.id]
  ); // +10 queries
  user.lessonsCompleted = progress.count;
}
// Total: 11 queries, 11 round-trips, ~1000% mais lento

-- BOM: 1 query com JOIN
const users = await db.query(
  `SELECT u.*, COUNT(p.id) as lessons_completed
   FROM users u
   LEFT JOIN user_lesson_progress p ON u.id = p.user_id 
     AND p.status = 'completed'
   GROUP BY u.id
   LIMIT 10`
); // 1 query, dados completos, 1 round-trip

-- Query comum: WHERE module_id = X AND status = 'completed'

-- Índice ruim (ordem errada)
CREATE INDEX idx_progress_status_module ON user_lesson_progress(status, module_id);
-- Usa apenas status; module_id ignorado

-- Índice bom (ordem certa)
CREATE INDEX idx_progress_module_status ON user_lesson_progress(module_id, status);
-- Usa ambas colunas: module_id (mais seletivo), depois status

EXPLAIN ANALYZE
SELECT * FROM user_lesson_progress WHERE module_id = X AND status = 'completed';
-- Com índice certo: Index Scan (rápido)

-- Sem covering
CREATE INDEX idx_progress_user_status ON user_lesson_progress(user_id, status);
SELECT * FROM user_lesson_progress WHERE user_id = X AND status = 'completed';
-- Lê índice, depois tabela (2 acessos, mais lento)

-- Com covering (PostgreSQL 11+)
CREATE INDEX idx_progress_user_status_covering ON user_lesson_progress(user_id, status)
  INCLUDE (completed_at, progress_percentage);
SELECT user_id, status, completed_at, progress_percentage 
FROM user_lesson_progress WHERE user_id = X AND status = 'completed';
-- Lê índice só (1 acesso, mais rápido)
